mapper.select:
SELECT COUNT(1) FROM t_as_schedule_period p INNER JOIN t_as_schedule_template t ON p.template_id = t.id WHERE t.school_id = #{schoolId} AND t.template_type = 2 AND t.enabled_status = 1 AND t.is_valid = 1 AND t.id != #{excludeTemplateId} AND p.period_type = 2 AND p.is_valid = 1 AND (
JSON_CONTAINS(p.grade_scope_json, CAST(#{gid} AS JSON))
)
